from _lib import *
lesson("subjunctive", "Tryby nierzeczywiste", "Tryb łączący (subjunctive) po suggest, insist, demand", 8,
 "Po czasownikach i wyrażeniach takich jak suggest, recommend, insist, demand, propose, request, require, it is essential/vital/important that używamy formy podstawowej czasownika (bez -s, bez czasu przeszłego) dla wszystkich osób: The doctor recommended that he rest. To tzw. present subjunctive. W brytyjskim angielskim alternatywą jest should + bezokolicznik.",
 "Subjunctive to cecha stylu formalnego: raporty, propozycje (Writing Part 2), oficjalne listy. Na egzaminie często sprawdzane w Open cloze i Part 4 (suggest/insist).",
 dict(scheme="suggest/insist/recommend + that + podmiot + forma podstawowa (lub should + forma podstawowa)", word_order="I suggest that she apply. / It is vital that everyone be informed.",
      affirmative=["The manager insisted that he attend the meeting.", "It is essential that every pupil have access to a computer.", "We recommend that the report be published."],
      negative=["She suggested that we not tell anyone.", "It is important that he not be disturbed."],
      questions=["Was it necessary that she leave so early?"]),
 [X("I suggest that he see a doctor.", "Sugeruję, żeby poszedł do lekarza.", "See bez -s (subjunctive)."),
  X("I suggest that he should see a doctor.", "Sugeruję, żeby poszedł do lekarza.", "Wersja brytyjska z should."),
  X("The committee recommended that the plan be rejected.", "Komisja zaleciła odrzucenie planu.", "Strona bierna: be + past participle."),
  X("She insisted that he pay for the damage.", "Nalegała, żeby zapłacił za szkody.", "Pay, mimo przeszłego insisted."),
  X("It is vital that all staff be trained.", "Kluczowe jest, aby cały personel został przeszkolony.", "It is vital that + be."),
  X("They demanded that the minister resign.", "Zażądali dymisji ministra.", "Resign bez -s."),
  X("We propose that the meeting be postponed.", "Proponujemy przełożenie spotkania.", "Typowe w propozycji."),
  X("It is important that she not miss the deadline.", "Ważne jest, żeby nie przegapiła terminu.", "Przeczenie: not + forma podstawowa (bez do)."),
  X("I suggest going by train.", "Proponuję pojechać pociągiem.", "Alternatywa: suggest + -ing."),
  X("The rules require that every visitor sign in.", "Przepisy wymagają, by każdy gość się wpisał.", "Require that + forma podstawowa."),
  X("If need be, we can stay longer.", "W razie potrzeby możemy zostać dłużej.", "Utarte wyrażenie z subjunctive.")],
 [C("suggest that he go vs suggest him to go", "Pierwsza forma poprawna; druga to częsty błąd – suggest nie łączy się z dopełnieniem + to.", "Używaj: suggest that sb (should) do / suggest doing."),
  C("subjunctive vs should + bezokolicznik", "Znaczenie identyczne; subjunctive jest bardziej formalny i amerykański, should – brytyjski.", "Oba poprawne na egzaminie."),
  C("insist that he go vs insist that he went", "Go – żądanie; went – twierdzenie o fakcie (upierał się, że poszedł).", "Znaczenie zależy od formy!")],
 [W("I suggest you to apply.", "I suggest that you apply. / I suggest applying.", "Suggest nie łączy się z dopełnieniem + to."),
  W("The doctor recommended that she rests.", "The doctor recommended that she rest.", "W subjunctive brak -s."),
  W("It is essential that he doesn't forget.", "It is essential that he not forget.", "Przeczenie bez do."),
  W("They demanded that he was punished.", "They demanded that he be punished.", "Strona bierna: be + past participle.")],
 ["W mowie potocznej wiele osób używa zwykłego czasu (I suggest he goes) – na egzaminie bezpieczniej subjunctive lub should.",
  "Utarte formy subjunctive: God save the King, Be that as it may, So be it, Come what may.",
  "Were jako subjunctive przeszły pojawia się w if I were, as if it were, wish it were."],
 [dict(en="It is imperative that the findings be shared with the public.", pl="Konieczne jest udostępnienie wyników opinii publicznej.", note="Imperative = konieczne (bardzo formalnie)."),
  dict(en="I would therefore recommend that the council reconsider its decision.", pl="Dlatego zalecałbym, aby rada ponownie rozważyła decyzję.", note="Gotowe zdanie do raportu/propozycji."),
  dict(en="Come what may, we will finish the project.", pl="Cokolwiek się stanie, ukończymy projekt.", note="Utarte wyrażenie.")],
 [G("The teacher suggested that she ___ (read) the book again.", ["read", "should read"], "Subjunctive: forma podstawowa."),
  G("It is essential that everyone ___ (be) on time.", ["be", "should be"], "Be dla wszystkich osób."),
  G("They insisted that the decision ___ (review).", ["be reviewed", "should be reviewed"], "Strona bierna."),
  M("I recommend that he ___ a lawyer.", ["consult", "consults", "consulted", "to consult"], "consult", "Bez -s.", {"consults": "Subjunctive nie ma końcówki -s.", "consulted": "Czas przeszły zmienia znaczenie.", "to consult": "Po that nie stawiamy to."}),
  G("It is important that he ___ (not / tell) anyone.", ["not tell", "should not tell", "shouldn't tell"], "Przeczenie: not tell."),
  K("'You should get some rest,' the doctor told him.", "SUGGESTED", "The doctor ___ some rest.", ["suggested that he get", "suggested that he should get", "suggested he get", "suggested he should get", "suggested getting"], "Suggest + that + forma podstawowa."),
  K("The boss said we absolutely had to attend.", "INSISTED", "The boss ___ attend.", ["insisted that we", "insisted that we should"], "Insist that we attend."),
  E("She suggested me to take a break.", ["She suggested that I take a break.", "She suggested that I should take a break.", "She suggested taking a break.", "She suggested I take a break."], "Suggest + that.")],
 [G("The report recommends that the scheme ___ (extend) to other cities.", ["be extended", "should be extended"], "Bierna."),
  K("Everyone must be informed – that's crucial.", "CRUCIAL", "It is ___ informed.", ["crucial that everyone be", "crucial that everyone should be", "crucial that everybody be"], "It is crucial that + be."),
  K("They demanded his resignation.", "RESIGN", "They demanded that ___.", ["he resign", "he should resign"], "Demand that he resign."),
  M("The rules require that each candidate ___ a photo.", ["submit", "submits", "will submit", "submitting"], "submit", "Subjunctive.", {"submits": "-s nie występuje w subjunctive.", "will submit": "Will nie pasuje po require that.", "submitting": "Po that potrzebne zdanie."}),
  G("I propose that the meeting ___ (hold) online.", ["be held", "should be held"], "Bierna: be held."),
  T("Nalegał, żebym został na kolację.", ["He insisted that I stay for dinner.", "He insisted that I should stay for dinner.", "He insisted on my staying for dinner.", "He insisted I stay for dinner."], "Insist that + forma podstawowa.")])
